-- Store unlocks that work on monster loot (bought in the store, see shop_services.lua / shop_config.lua):
--
-- Auto Seller (storage Chaos.storage.shopAutoSeller): items on the character's auto-sell list are taken out of
--   the corpses the character owns and sold at once at the NPC price (sell_prices.lua, generated by
--   server/tools/gen_sell_prices.py); the gold goes into the bank. The list is separate from the autoloot list,
--   so an item does not need an autoloot slot. Items with a rarity, modifiers or a custom name/description are
--   kept unless the player opted in ("!autosell rarity on"); unique items are never sold.
--   !autosell add <item> | remove <item> | list | clear | on | off | rarity on|off
-- Bottomless Loot Pouch (storage Chaos.storage.shopLootPouch): autoloot items the base autoloot callback could
--   not give to the character (backpack full, no capacity) go to the supply stash (stackable, attribute-free
--   items, stash.lua rules) or else to the character's inbox, instead of staying in the corpse.
--
-- Both are EventCallback.onDropLoot, around the callbacks that already exist (lower index runs first):
--   0 stock loot, 1 Chaos loot layer (loot.lua), 2 AUTO SELLER, 3 base autoloot, 4 LOOT POUCH.

if not Chaos then
	dofile("data/scripts/chaos/chaos_constants.lua")
end

local ST = Chaos.storage
local S = ChaosShopServices -- pure helpers (shop_services.lua); looked up again at run time if nil at load
local SLOTS = Chaos.shopServices.autosellSlots
local PRICES = dofile("data/scripts/chaos/sell_prices.lua")
local CUSTOM = 2147483648 -- ITEM_ATTRIBUTE_CUSTOM (1 << 31): not exported to Lua by the engine

local function services()
	S = S or ChaosShopServices
	return S
end

ChaosAutoSell = ChaosAutoSell or {}
local A = ChaosAutoSell
A.prices = PRICES

-- ------------------------------------------------------------------------ list in storages
local function readList(player)
	local list = {}
	for i = 1, SLOTS do
		local id = player:getStorageValue(ST.autosellBase + i)
		if id and id > 0 then
			list[#list + 1] = id
		end
	end
	return list
end

local function writeList(player, list)
	for i = 1, SLOTS do
		player:setStorageValue(ST.autosellBase + i, list[i] or -1)
	end
end

local function listSet(player)
	local set = {}
	for _, id in ipairs(readList(player)) do
		set[id] = true
	end
	return set
end

-- ------------------------------------------------------------------------ item checks
local function customAttr(item, key)
	local ok, v = pcall(function() return item:getCustomAttribute(key) end)
	return ok and v or nil
end

local function itemInfo(item)
	return {
		unique = customAttr(item, "chaos_unique") ~= nil,
		rarity = tonumber(customAttr(item, "rarity")) or 0,
		attributes = item:hasAttribute(ITEM_ATTRIBUTE_NAME) or item:hasAttribute(ITEM_ATTRIBUTE_DESCRIPTION)
			or item:hasAttribute(ITEM_ATTRIBUTE_TEXT) or item:hasAttribute(CUSTOM)
	}
end
A.itemInfo = itemInfo

-- ------------------------------------------------------------------------ auto seller (index 2)
local function autoSell(monster, corpse)
	if not corpse:getType():isContainer() then
		return
	end
	local owner = Player(corpse:getCorpseOwner())
	if not owner or owner:getStorageValue(ST.shopAutoSeller) < 1 or owner:getStorageValue(ST.autosellPaused) == 1 then
		return
	end
	local set = listSet(owner)
	if next(set) == nil then
		return
	end
	local allowRarity = owner:getStorageValue(ST.autosellRarity) == 1
	local sold, total, kept = {}, 0, 0
	for _, item in ipairs(corpse:getItems()) do
		local id = item:getId()
		if set[id] and not item:getType():isContainer() then
			local count = item:getCount()
			local gold = services().sellPrice(id, count, PRICES)
			if gold > 0 then
				if services().sellBlocked(itemInfo(item), allowRarity) then
					kept = kept + 1
				else
					local name = item:getType():getName()
					if item:remove() then
						total = total + gold
						sold[#sold + 1] = (count > 1 and (count .. "x ") or "") .. name
					end
				end
			end
		end
	end
	if total > 0 then
		owner:setBankBalance(owner:getBankBalance() + total)
		owner:sendTextMessage(MESSAGE_LOOT or MESSAGE_INFO_DESCR, string.format("Auto seller: sold %s for %d gold (to your bank).",
			table.concat(sold, ", "), total))
	end
	if kept > 0 then
		owner:sendTextMessage(MESSAGE_LOOT or MESSAGE_INFO_DESCR,
			"Auto seller: kept an item with a rarity or modifiers (\"!autosell rarity on\" sells those too).")
	end
end

local sellCb = EventCallback
sellCb.onDropLoot = function(self, corpse)
	local ok, err = pcall(autoSell, self, corpse)
	if not ok then
		print("[Chaos autosell] onDropLoot failed: " .. tostring(err))
	end
end
sellCb:register(2)

-- ------------------------------------------------------------------------ loot pouch (index 4)
local pending = {} -- [guid] = {stash = n, inbox = n, last = os.time of the last notice}

local function autolootSet(player)
	local limit = player:isPremium() and Chaos.autoloot.premiumLimit or Chaos.autoloot.freeLimit
	local set = {}
	for i = 1, limit do
		local id = player:getStorageValue(ST.autolootBase + i)
		if id and id > 0 then
			set[id] = true
		end
	end
	return set
end

local function notify(player)
	local p = pending[player:getGuid()]
	local now = os.time()
	if not p or p.stash + p.inbox == 0 or now - p.last < Chaos.shopServices.pouchNoticeSeconds then
		return
	end
	local parts = {}
	if p.stash > 0 then
		parts[#parts + 1] = p.stash .. " to your stash"
	end
	if p.inbox > 0 then
		parts[#parts + 1] = p.inbox .. " to your inbox"
	end
	player:sendTextMessage(MESSAGE_LOOT or MESSAGE_INFO_DESCR, "Loot pouch: your backpack is full, loot sent " ..
		table.concat(parts, " and ") .. " (!stash).")
	p.stash, p.inbox, p.last = 0, 0, now
end

local function pouch(monster, corpse)
	if not corpse:getType():isContainer() then
		return
	end
	local owner = Player(corpse:getCorpseOwner())
	if not owner or owner:getStorageValue(ST.shopLootPouch) < 1 then
		return
	end
	local set = autolootSet(owner)
	if next(set) == nil then
		return
	end
	local guid = owner:getGuid()
	pending[guid] = pending[guid] or {stash = 0, inbox = 0, last = 0}
	local p = pending[guid]
	local leftovers = {}
	for _, item in ipairs(corpse:getItems()) do
		if set[item:getId()] then
			leftovers[#leftovers + 1] = item
		end
	end
	for _, item in ipairs(leftovers) do
		-- the base autoloot stops at the first item that does not fit; a lighter one may still fit
		if not item:moveTo(owner) then
			if ChaosStash and ChaosStash.storeItem(owner, item) then
				p.stash = p.stash + 1
			else
				local inbox = owner:getInbox()
				if inbox and item:moveTo(inbox) then
					p.inbox = p.inbox + 1
				end
			end
		end
	end
	notify(owner)
end

local pouchCb = EventCallback
pouchCb.onDropLoot = function(self, corpse)
	local ok, err = pcall(pouch, self, corpse)
	if not ok then
		print("[Chaos loot pouch] onDropLoot failed: " .. tostring(err))
	end
end
pouchCb:register(4)

local logout = CreatureEvent("ChaosLootPouchLogout")
function logout.onLogout(player)
	pending[player:getGuid()] = nil
	return true
end
logout:register()

local login = CreatureEvent("ChaosLootPouchLogin")
function login.onLogin(player)
	player:registerEvent("ChaosLootPouchLogout")
	return true
end
login:register()

-- ------------------------------------------------------------------------ !autosell
local function lookup(text)
	local it = ItemType(text)
	if it and it:getId() ~= 0 then
		return it
	end
	local n = tonumber(text)
	if n then
		it = ItemType(n)
		if it and it:getId() ~= 0 then
			return it
		end
	end
	return nil
end

local HELP = "Auto seller: !autosell add <item> | remove <item> | list | clear | on | off | rarity on|off"

local talk = TalkAction("!autosell")
function talk.onSay(player, words, param)
	if player:getStorageValue(ST.shopAutoSeller) < 1 then
		player:sendCancelMessage("You need the Auto Seller from the store (Convenience).")
		return false
	end
	local action, arg = (param or ""):match("^%s*(%S*)%s*,?%s*(.-)%s*$")
	action = (action or ""):lower()
	local list = readList(player)
	if action == "add" or action == "remove" then
		local it = lookup(arg)
		if not it then
			player:sendCancelMessage("There is no item called " .. arg .. ".")
			return false
		end
		local id, index = it:getId(), nil
		for i, v in ipairs(list) do
			if v == id then
				index = i
			end
		end
		if action == "add" then
			if index then
				player:sendCancelMessage(it:getName() .. " is already on your auto-sell list.")
			elseif (PRICES[id] or 0) <= 0 then
				player:sendCancelMessage("No NPC buys " .. it:getName() .. ", so it cannot be auto-sold.")
			elseif #list >= SLOTS then
				player:sendCancelMessage("Your auto-sell list is full (" .. SLOTS .. " items).")
			else
				list[#list + 1] = id
				writeList(player, list)
				player:sendTextMessage(MESSAGE_INFO_DESCR, string.format("Auto seller: %s will be sold for %d gold each.", it:getName(), PRICES[id]))
			end
		elseif index then
			table.remove(list, index)
			writeList(player, list)
			player:sendTextMessage(MESSAGE_INFO_DESCR, "Auto seller: removed " .. it:getName() .. ".")
		else
			player:sendCancelMessage(it:getName() .. " is not on your auto-sell list.")
		end
	elseif action == "list" or action == "" then
		local lines = {}
		for _, id in ipairs(list) do
			lines[#lines + 1] = string.format("%s (%d gold)", ItemType(id):getName(), PRICES[id] or 0)
		end
		player:sendTextMessage(MESSAGE_INFO_DESCR, string.format("Auto seller is %s, rarity items %s. %d/%d items: %s\n%s",
			player:getStorageValue(ST.autosellPaused) == 1 and "OFF" or "ON",
			player:getStorageValue(ST.autosellRarity) == 1 and "are sold" or "are kept",
			#list, SLOTS, #lines > 0 and table.concat(lines, ", ") or "-", HELP))
	elseif action == "clear" then
		writeList(player, {})
		player:sendTextMessage(MESSAGE_INFO_DESCR, "Auto seller: list cleared.")
	elseif action == "on" or action == "off" then
		player:setStorageValue(ST.autosellPaused, action == "off" and 1 or 0)
		player:sendTextMessage(MESSAGE_INFO_DESCR, "Auto seller is now " .. action:upper() .. ".")
	elseif action == "rarity" then
		local on = arg:lower() == "on"
		player:setStorageValue(ST.autosellRarity, on and 1 or 0)
		player:sendTextMessage(MESSAGE_INFO_DESCR, on
			and "Auto seller: items with a rarity or modifiers on your list are now sold too (uniques never are)."
			or "Auto seller: items with a rarity or modifiers are kept.")
	else
		player:sendTextMessage(MESSAGE_INFO_DESCR, HELP)
	end
	return false
end
talk:separator(" ")
talk:register()
